"""Write docs/RESULTS.md from the cached frontier (generated; do not edit by hand).

    python -m site_engine.report
"""
from __future__ import annotations

import datetime as dt
from pathlib import Path

from . import ENGINE, SITE_MODEL_VERSION
from . import library as lib
from . import precompute as pc


def full_section():
    """Full order finding at n = 2048 (Stage 11: the one full-run pricer, `fullalg`)."""
    from . import full_frontier as ff
    from . import fullalg as fa
    lines = ["## Full order finding at n = 2048", "",
             f"Pricer: {fa.TIER}. {fa.CENSUS_TRUST}. Qubits: Lean's static layout (allocateReferenceLayout). The grid-leaf "
             "column is a cross-check (Lean's W x W grid leaf, NaiveLeaf.lean:53), not the score.", "",
             "| policy | single-run T (1e-2) | grid-leaf cross-check (1e-2) | qubits | single-run T (1e-4) | single-run T (1e-6) |",
             "|---|---:|---:|---:|---:|---:|"]
    cs = {d: ff.load(d) for d in pc.PRESET_DELTAS}
    if cs[1e-2] is None:
        return lines + ["", "_cache missing: run `python -m site_engine.full_frontier`_", ""]
    t = lambda d, i: f"{cs[d]['hero']['milestones'][i]['T']:.4e}" if cs.get(d) else "not computed"
    for i, h in enumerate(cs[1e-2]["hero"]["milestones"]):
        lines.append(f"| {dict((k, l) for k, l, _ in lib.MILESTONES)[h['key']]} | {t(1e-2, i)} | {h['lean_grid_leaf_T']:.4e} | "
                     f"{h['qubits']:,} | {t(1e-4, i)} | {t(1e-6, i)} |")
    s = cs[1e-2]["forshor_shipped"]
    lines.append(f"| {s['label']} | {s['T']:.4e} | {s['lean_grid_leaf_T']:.4e} | {s['qubits']:,} | | |")
    best = cs[1e-2]["leaderboard"]["ranked"][0]
    lines += ["", f"Best leaderboard row (delta = 1e-2): {best['id']}, {best['T']:.4e} T, {best['qubits']:,} qubits, main ladder "
              f"`{best['ladder_str']}`.", "",
              f"The paper's printed figure, reproduced in the retired paper model (R2 widths, version C, no Step 4): "
              f"{cs[1e-2]['paper']['r2_T_2048']:.4e} T. Not comparable with the rows.", ""]
    return lines


def seeds_section():
    """The 31 seeded policy records, re-planned under exact widths (Stage 13): old (scanned) vs new (exact)."""
    from . import frontier as fr
    from . import submitted
    from tcost import tables as tt
    lines = ["## Seeded policy records, re-planned under exact widths (n = 2048, delta = 1e-2)", "",
             "Old: the seed as planned at scanned widths (record history), priced at scanned widths. New: re-planned under "
             "exact widths over its own tables, priced at exact widths. Qubits: PP the static-layout formula at exact widths "
             "(not Lean-proved; old = Lean static at scanned widths); PTP Qualtran's peak. Lean: the pinned exact-width run.", "",
             "| id | mode | old bands | new bands | exact ladder 2048 | old T | new T | old qubits | new qubits | Lean (exact) |",
             "|---|---|---|---|---|---:|---:|---:|---:|---|"]
    for r in sorted(submitted.seeded(), key=lambda r: (r["mode"], r["id"])):
        d = Path(r["site_policy_path"]).parent
        new = tt.load_policies(d / "site_policy.json")[0]
        old = tt.load_policies(d / "site_policy.pre_exact.json")[0].with_widths("scan")
        po, pn = fr.point(old, fr.HERO_N, 1e-2, check=False), fr.point(new, fr.HERO_N, 1e-2, check=False)
        b = lambda P: ", ".join(f"{x.threshold}:{x.table.k}" for x in P.bands)
        m = r.get("sto_mirror") or {}
        lines.append(f"| {r['id']} | {'PP' if r['mode'] == tt.PAIR else 'PTP'} | {b(old)} | {b(new)} | {pn['ladder_str']} | "
                     f"{round(po['T']):,} | {round(pn['T']):,} | {po['qubits']:,} | {pn['qubits']:,} | {m.get('status')} |")
    return lines + [""]


def main() -> int:
    from . import frontier as fr
    lines = [f"# Results (generated by `python -m site_engine.report`, {dt.date.today().isoformat()})", "",
             f"Model `{SITE_MODEL_VERSION}`, data fingerprint `{pc.data_fingerprint()}`. PP digital-product leaf, PTP digital triple-product leaf (Stage 17; the grid leaf is a cross-check), "
             "And = 4 T, rotation = 3.075 log2(1/eps) + 0.86 T (unrounded), eps = 0.5 delta / R.", "",
             "Widths (PLAN_v2 Stage 13): the PhaseProduct and PhaseTripleProduct boards are planned and priced at EXACT widths "
             "(the least width at which every reachable register value and child operand fits, floor limbs). The last column "
             "is the same milestone planned and priced at ForShor's scanned widths (the rule before 2026-10-28), a labelled "
             "cross-check. The full order-finding section prices the ForShor drop-in IR (Stage 18: exact widths + balanced split), "
             "with upstream ForShor's scanned-width IR as its cross-check.", ""]
    for mode in lib.MODES:
        lines += [f"## {mode} at n = 2048", "",
                  "| milestone | delta = 1e-2 | delta = 3e-4 | delta = 1e-4 | delta = 1e-6 | below reference (1e-2) | scanned widths (1e-2, cross-check) |",
                  "|---|---:|---:|---:|---:|---:|---:|"]
        cs = {d: pc.load(mode, d) for d in pc.PRESET_DELTAS}
        if cs[1e-2] is None:
            lines += ["", "_cache missing: run `python -m site_engine.precompute`_", ""]
            continue
        missing = [d for d, c in cs.items() if c is None]
        cs = {d: c for d, c in cs.items() if c is not None}
        t = lambda d, i: f"{round(cs[d]['hero']['milestones'][i]['T']):,}" if d in cs else "not computed"
        for i, (key, label, _) in enumerate(lib.MILESTONES):
            r = cs[1e-2]["hero"]["milestones"][i]
            scan = (fr.point(lib.reference_policies()[mode].with_widths("scan"), fr.HERO_N, 1e-2, check=False, with_qubits=False)
                    if key == "reference" else fr.planned(key, mode, fr.HERO_N, 1e-2, "scan")[1])
            lines.append(f"| {label} | {t(1e-2, i)} | {t(3e-4, i)} | {t(1e-4, i)} | {t(1e-6, i)} | {r['below_reference_pct']:.2f}% "
                         f"| {round(scan['T']):,} |")
        if missing:
            lines += ["", "_Columns marked not computed need `python -m site_engine.precompute` (minutes)._"]
        best = cs[1e-2]["hero"]["milestones"][-1]
        lines += ["", f"Best policy (+ DP library, delta = 1e-2): `{best['ladder_str']}`, tables {best['label']}.", ""]
        pts = [p for c in cs.values() for m in c["milestones"].values() for p in m["points"]]
        agree = sum(p["agree"] for p in pts)
        lines += [f"Engine agreement over every cached point of this mode: {agree} / {len(pts)}.", ""]
        lb = cs[1e-2]["leaderboard"]
        adv = [r for r in lb["rows"] if r["advance"]]
        lines += [f"Leaderboard (delta = 1e-2): {len(lb['rows'])} submissions with {mode} tables, {len(adv)} frontier "
                  f"advances, from {round(lb['start']['T']):,} T (leaf only, no table) to {round(lb['rows'][-1]['T']):,} T.", ""]
    lines += seeds_section()
    lines += full_section()
    out = ENGINE.parent / "docs" / "RESULTS.md"
    out.write_text("\n".join(lines) + "\n")
    print(out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
